// OpenNext's generated Worker exports fetch only. This wrapper preserves
// all Next.js request handling and adds a Cloudflare scheduled handler.
// @ts-ignore Generated by `npx @opennextjs/cloudflare build`
import handler from './.open-next/worker.js'
 
// Preserve OpenNext Durable Object exports used for ISR/cache invalidation.
// @ts-ignore Generated at build time
export { DOQueueHandler, DOShardedTagCache } from './.open-next/worker.js'

type ScheduledEvent = { scheduledTime: number }
type SyncEnv = { DRUG_SYNC_SECRET?: string }
type Ctx = { waitUntil(promise: Promise<unknown>): void }

function cairoHour(scheduledTime: number) {
  const parts = new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Africa/Cairo', hour: '2-digit', hourCycle: 'h23',
  }).formatToParts(new Date(scheduledTime))
  return Number(parts.find((p) => p.type === 'hour')?.value || -1)
}

export default {
  fetch: handler.fetch,
  async scheduled(event: ScheduledEvent, env: SyncEnv, ctx: Ctx) {
    const hour = cairoHour(event.scheduledTime)
    // UTC cron runs more than once so Egypt DST (UTC+2/+3) remains correct.
    // 06:00 Cairo is the daily start. Hourly 07-09 retries only on failure;
    // the endpoint checks lastSuccessDate and skips successful days.
    if (hour < 6 || hour > 9) return
    const secret = env.DRUG_SYNC_SECRET
    if (!secret || secret.length < 32) {
      throw new Error('DRUG_SYNC_SECRET_MISSING: set secret in Cloudflare Worker')
    }
    const call = new Request('https://yalla-clinic.com/api/sync-daily-prices', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-drug-sync-secret': secret,
      },
      body: JSON.stringify({}),
    })
    // Call the generated Next handler directly, not a public unauthenticated URL.
    const response: Response = await handler.fetch(call, env, ctx)
    const result = await response.json().catch(() => ({})) as {
      success?: boolean; skipped?: boolean; updated_count?: number; error?: string; code?: string
    }
    if (!response.ok || !result.success) {
      throw new Error(`DRUG_SYNC_CRON_FAILED_${response.status}: ${result.code || result.error || 'unknown'}`)
    }
    console.log('[drug-sync] cron finished', {
      cairoHour: hour,
      skipped: Boolean(result.skipped),
      updated: result.updated_count || 0,
    })
  },
}
